import { test, expect } from '@playwright/test';

test.describe('Internet Connection Drop Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display friendly error message when internet connection drops', async ({ page }) => {
    // Setup: Mock the network response to simulate a dropped connection
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 100));
      route.abort('Connection dropped');
    });

    // Intercept the initial data fetch request
    const dataRequest = page.waitForResponse('**/api/data');
    await dataRequest.abort();

    // Verify error message is visible
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Unable to load data');

    // Verify error message has a dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify error message has a retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify error message has a link to network settings
    const networkSettingsLink = page.getByRole('link', { name: /network settings/i });
    await expect(networkSettingsLink).toBeVisible();

    // Verify error message has a timestamp
    const timestamp = page.getByText(/at \d{2}:\d{2}:\d{2}/);
    await expect(timestamp).toBeVisible();

    // Verify error message has a user-friendly icon
    const icon = page.getByRole('img', { name: /no connection/i });
    await expect(icon).toBeVisible();

    // Verify error message is styled appropriately
    const errorClass = page.getByTestId('error-message');
    await expect(errorClass).toHaveClass(/is-visible/);

    // Verify error message is not displayed when connection is restored
    await page.route('**/api/data', async (route) => {
      await route.continue();
    });

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify dashboard content is restored
    const dashboardContent = page.getByRole('main');
    await expect(dashboardContent).toBeVisible();

    // Verify data is now visible
    const dataTable = page.getByRole('table');
    await expect(dataTable).toBeVisible();

    // Verify data is loaded
    const dataRows = page.locator('[data-testid="data-row"]');
    await expect(dataRows).toHaveCount(3);
  });

  test('should not display error message when internet connection is restored', async ({ page }) => {
    // Setup: Mock the network response to simulate a dropped connection
    await page.route('**/api/data', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 100));
      route.abort('Connection dropped');
    });

    // Intercept the initial data fetch request
    const dataRequest = page.waitForResponse('**/api/data');
    await dataRequest.abort();

    // Verify error message is displayed
    const errorMessage = page.getByRole('alert');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Unable to load data');

    // Verify error message has a dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify error message has a retry button
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify error message has a link to network settings
    const networkSettingsLink = page.getByRole('link', { name: /network settings/i });
    await expect(networkSettingsLink).toBeVisible();

    // Verify error message has a timestamp
    const timestamp = page.getByText(/at \d{2}:\d{2}:\d{2}/);
    await expect(timestamp).toBeVisible();

    // Verify error message has a user-friendly icon
    const icon = page.getByRole('img', { name: /no connection/i });
    await expect(icon).toBeVisible();

    // Verify error message is styled appropriately
    const errorClass = page.getByTestId('error-message');
    await expect(errorClass).toHaveClass(/is-visible/);

    // Restore the connection
    await page.route('**/api/data', async (route) => {
      await route.continue();
    });

    // Verify error message disappears
    await expect(errorMessage).not.toBeVisible();

    // Verify dashboard content is restored
    const dashboardContent = page.getByRole('main');
    await expect(dashboardContent).toBeVisible();

    // Verify data is now visible
    const dataTable = page.getByRole('table');
    await expect(dataTable).toBeVisible();

    // Verify data is loaded
    const dataRows = page.locator('[data-testid="data-row"]');
    await expect(dataRows).toHaveCount(3);
  });
});
